CREATE   PROCEDURE [synapse_fo].[usp_Insert_VENDPACKINGSLIPTRANS]
AS
BEGIN

	INSERT INTO [synapse_fo].[VENDPACKINGSLIPTRANS]
	(
		[recid],
		[sinkcreatedon],
		[SinkModifiedOn],
		[fullymatched],
		[inventreftype],
		[stockedproduct],
		[sysdatastatecode],
		[destcountryregionid],
		[acceptedqty_in],
		[accountingdate],
		[costledgervoucher],
		[currencycode_w],
		[defaultdimension],
		[destcounty],
		[deviationqty_ru],
		[exciseamount_ru],
		[excisevalue_ru],
		[externalitemid],
		[intercompanyinventtransid],
		[inventdate],
		[inventdimid],
		[inventqty],
		[inventrefid],
		[inventreftransid],
		[inventtransid],
		[itemid],
		[lineamount_w],
		[linenum],
		[name],
		[ngpcodestable_fr],
		[ordered],
		[origcountryregionid],
		[origpurchid],
		[origstateid],
		[packingslipid],
		[pdscwordered],
		[pdscwqty],
		[pdscwremain],
		[port],
		[priceunit],
		[procurementcategory],
		[purchaselineexpecteddeliverydate],
		[purchaselinelinenumber],
		[purchunit],
		[qty],
		[reasontableref],
		[receivedqty_in],
		[rejectedqty_in],
		[remain],
		[remaininvent],
		[returnactionid],
		[sourcedocumentline],
		[statisticvalue_lt],
		[statprocid],
		[taxamount_ru],
		[taxgroup_ru],
		[transactioncode],
		[transport],
		[valuemst],
		[vatamount_ru],
		[vatvalue_ru],
		[vendpackingslipjour],
		[weight],
		[workerpurchaser],
		[itemcodeid],
		[cancelledqty],
		[modifiedon],
		[modifiedby],
		[createdon],
		[createdby],
		[dataareaid],
		[IsDelete]
	)
	SELECT
		src.[recid],
		src.[sinkcreatedon],
		src.[SinkModifiedOn],
		src.[fullymatched],
		src.[inventreftype],
		src.[stockedproduct],
		src.[sysdatastatecode],
		src.[destcountryregionid],
		src.[acceptedqty_in],
		src.[accountingdate],
		src.[costledgervoucher],
		src.[currencycode_w],
		src.[defaultdimension],
		src.[destcounty],
		src.[deviationqty_ru],
		src.[exciseamount_ru],
		src.[excisevalue_ru],
		src.[externalitemid],
		src.[intercompanyinventtransid],
		src.[inventdate],
		src.[inventdimid],
		src.[inventqty],
		src.[inventrefid],
		src.[inventreftransid],
		src.[inventtransid],
		src.[itemid],
		src.[lineamount_w],
		src.[linenum],
		src.[name],
		src.[ngpcodestable_fr],
		src.[ordered],
		src.[origcountryregionid],
		src.[origpurchid],
		src.[origstateid],
		src.[packingslipid],
		src.[pdscwordered],
		src.[pdscwqty],
		src.[pdscwremain],
		src.[port],
		src.[priceunit],
		src.[procurementcategory],
		src.[purchaselineexpecteddeliverydate],
		src.[purchaselinelinenumber],
		src.[purchunit],
		src.[qty],
		src.[reasontableref],
		src.[receivedqty_in],
		src.[rejectedqty_in],
		src.[remain],
		src.[remaininvent],
		src.[returnactionid],
		src.[sourcedocumentline],
		src.[statisticvalue_lt],
		src.[statprocid],
		src.[taxamount_ru],
		src.[taxgroup_ru],
		src.[transactioncode],
		src.[transport],
		src.[valuemst],
		src.[vatamount_ru],
		src.[vatvalue_ru],
		src.[vendpackingslipjour],
		src.[weight],
		src.[workerpurchaser],
		src.[itemcodeid],
		src.[cancelledqty],
		src.[modifiedon],
		src.[modifiedby],
		src.[createdon],
		src.[createdby],
		src.[dataareaid],
		src.[IsDelete]	
	FROM [staging_fo].[VENDPACKINGSLIPTRANS] src
		LEFT JOIN [synapse_fo].[VENDPACKINGSLIPTRANS] tgt
			ON src.[RecId] = tgt.[RecId]
			AND src.[DataAreaId] = tgt.[DataAreaId]
	WHERE tgt.[RecId] IS NULL

END
